//
// Healthcare-specific PHI redactor. Use whenever a clinical-data-bearing object
// might leak into a log, error stack, exception, or third-party error tracker.
//
// Beyond generic PII patterns, this redactor strips clinical free-text fields
// (notes, diagnosis, symptom descriptions) and structured clinical values.

import { redact as baseRedact } from './audit_log';

// Clinical field names commonly seen in EMR / EHR schemas.
const CLINICAL_FIELD_NAMES = new Set([
  'diagnosis', 'icd10', 'icd_10', 'snomed', 'snomed_ct',
  'prescription', 'medication', 'drug', 'dosage', 'rx',
  'lab_result', 'lab_results', 'lab_value', 'test_result',
  'vital_signs', 'bp', 'pulse', 'spo2', 'temperature', 'heart_rate',
  'symptom', 'symptoms', 'symptom_notes', 'chief_complaint',
  'treatment', 'treatment_plan', 'procedure',
  'allergy', 'allergies', 'medical_history',
  'note', 'notes', 'soap_note', 'physician_note',
  'encounter', 'encounter_summary',
]);

// Free-text fields that often hide PHI within them.
const FREE_TEXT_CLINICAL_HINTS = [
  /\bpatient (was|is|has)\b/i,
  /\bdiagnos(ed|is)\b/i,
  /\bprescrib(ed|ing)\b/i,
  /\bmg\b|\bml\b|\biu\b/i,
];

function isClinicalText(value: string): boolean {
  return FREE_TEXT_CLINICAL_HINTS.some((re) => re.test(value));
}

/**
 * Redact PHI from any value before it enters a log / error / external sink.
 *
 * Use BEFORE:
 *   - throwing an error (especially one routed to Sentry / Datadog)
 *   - logging via console / logger
 *   - serialising to a metric label
 */
export function phiRedact<T>(value: T): T {
  if (value == null) return value;

  if (value instanceof Error) {
    const e = value as Error & { cause?: unknown; meta?: unknown };
    const copy = new Error(typeof e.message === 'string' && isClinicalText(e.message) ? '[PHI_REDACTED]' : e.message);
    copy.name = e.name;
    (copy as Error & { cause?: unknown }).cause = phiRedact(e.cause);
    return copy as unknown as T;
  }

  if (typeof value === 'string') {
    if (isClinicalText(value)) return '[PHI_REDACTED]' as unknown as T;
    return baseRedact(value);
  }

  if (Array.isArray(value)) {
    return value.map((v) => phiRedact(v)) as unknown as T;
  }

  if (typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (CLINICAL_FIELD_NAMES.has(k.toLowerCase())) {
        out[k] = '[PHI_REDACTED]';
      } else {
        out[k] = phiRedact(v);
      }
    }
    return out as unknown as T;
  }

  return value;
}

/**
 * Convenience: wrap an unknown error so log/throw sites can stay terse.
 *
 *   try { ... } catch (e) { logger.error('lookup failed', { err: redactErr(e) }); throw e; }
 */
export function redactErr(e: unknown): unknown {
  if (e instanceof Error) return phiRedact(e);
  return phiRedact(e as Record<string, unknown>);
}
